#include <cstdio>
#include <vector>
#include <string>
#include <iostream>

int main() {
    std::string hay, nee;
    std::getline(std::cin, hay);
    std::getline(std::cin, nee);

    if (nee.empty()) { printf("0\n"); return 0; }

    int n = (int)hay.size(), m = (int)nee.size();

    // 1) 前缀函数
    std::vector<int> pi(m, 0);
    for (int i = 1; i < m; ++i) {
        int j = pi[i - 1];
        while (j > 0 && nee[i] != nee[j]) j = pi[j - 1];
        if (nee[i] == nee[j]) ++j;
        pi[i] = j;
    }

    // 2) 匹配
    int j = 0, ans = -1;
    for (int i = 0; i < n; ++i) {
        while (j > 0 && hay[i] != nee[j]) j = pi[j - 1];
        if (hay[i] == nee[j]) ++j;
        if (j == m) { ans = i - m + 1; break; }
    }
    printf("%d\n", ans);
    return 0;
}
